import workcell, re, time
def c(*a):
    r = workcell.call(*[str(x) for x in a]); print(">", " ".join(map(str,a)), "=>", r.text.strip()); return r
def locate():
    for _ in range(3):
        r = workcell.call("vision","locate")
        m = re.search(r"lower end x=(-?[\d.]+) y=(-?[\d.]+) z=(-?[\d.]+) mm; tilt ([\d.]+)", r.text)
        if m: break
    hole = re.search(r"hole centre: x=(-?[\d.]+) y=(-?[\d.]+)", r.text)
    top = re.search(r"top at z=(-?[\d.]+)", r.text)
    return (float(hole.group(1)),float(hole.group(2))),(float(m.group(1)),float(m.group(2)),float(m.group(3))),float(m.group(4)),float(top.group(1))
def fz():
    for _ in range(3):
        r = workcell.call("robot","force","right")
        m = re.search(r"Fz=(-?[\d.]+)", r.text)
        if m: return float(m.group(1))
    return 0.0
for i in range(30):
    f=fz(); hole,peg,tilt,top=locate()
    print("descend tipz",peg[2],"Fz",f,"tilt",tilt)
    if f<-8: break
    c("robot","step","right",0,0,-5)
for i in range(12):
    hole,peg,tilt,top=locate(); f=fz()
    print("insert tipz",peg[2],"Fz",f,"tilt",tilt)
    if peg[2] <= top-38: break
    if f<-20: break
    c("robot","step","right",0,0,-4)
EOF

